import * as vscode from "vscode";
// @ts-ignore - configstore doesn't have TypeScript definitions
const Configstore = require("configstore");
// @ts-ignore - package.json import
const packageJson = require("../../../package.json");

export interface TranslationConfig {
  sourceLanguage: string;
  targetLanguages: string[];
  fileTypes: string[];
  aiProvider: "openai" | "gemini" | "mistral";
  model?: string;
  batchSize?: number;
  outputDirectory?: string;
  rateLimit?: {
    requestsPerMinute: number;
    tokensPerMinute: number;
  };
}

export class ConfigManager {
  private config: vscode.WorkspaceConfiguration;
  private secrets: any;

  constructor() {
    this.config = vscode.workspace.getConfiguration("localizer-ai");
    this.secrets = new Configstore(`${packageJson.name}-secrets`);
  }

  /**
   * Get API key for specified provider
   */
  getApiKey(provider: "openai" | "gemini" | "mistral"): string {
    // First try VS Code settings
    const key = this.config.get(`${provider}.apiKey`, "") as string;
    if (key && typeof key === "string" && key.trim()) {
      return key.trim();
    }

    // Fallback to secrets store
    const storedKey = this.secrets.get(`${provider}.apiKey`, "");
    return typeof storedKey === "string" ? storedKey : "";
  }

  /**
   * Set API key for specified provider
   */
  setApiKey(provider: "openai" | "gemini" | "mistral", key: string): void {
    this.secrets.set(`${provider}.apiKey`, key);
  }

  /**
   * Reset all API keys
   */
  resetApiKeys(): void {
    ["openai", "gemini", "mistral"].forEach((provider) => {
      this.secrets.delete(`${provider}.apiKey`);
    });
  }

  /**
   * Get default model
   */
  getDefaultModel(): string {
    return this.config.get("model", "gpt-4");
  }

  /**
   * Get AI provider
   */
  getAiProvider(): "openai" | "gemini" | "mistral" {
    return this.config.get("aiProvider", "openai");
  }

  /**
   * Get source language
   */
  getSourceLanguage(): string {
    return this.config.get("defaultSourceLanguage", "en");
  }

  /**
   * Get target languages
   */
  getTargetLanguages(): string[] {
    return this.config.get("defaultTargetLanguages", ["es", "fr", "de"]);
  }

  /**
   * Get batch size
   */
  getBatchSize(): number {
    return this.config.get("batchSize", 10);
  }

  /**
   * Get rate limit settings
   */
  getRateLimit(): { requestsPerMinute: number; tokensPerMinute: number } {
    return {
      requestsPerMinute: this.config.get("rateLimit.requestsPerMinute", 60),
      tokensPerMinute: this.config.get("rateLimit.tokensPerMinute", 10000),
    };
  }

  /**
   * Check if workspace config exists
   */
  async hasWorkspaceConfig(): Promise<boolean> {
    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    if (!workspaceFolder) {
      return false;
    }

    try {
      await vscode.workspace.fs.stat(
        vscode.Uri.joinPath(workspaceFolder.uri, "localizer-ai.config.json")
      );
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Read workspace configuration
   */
  async readWorkspaceConfig(): Promise<TranslationConfig | null> {
    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    if (!workspaceFolder) {
      return null;
    }

    try {
      const configUri = vscode.Uri.joinPath(
        workspaceFolder.uri,
        "localizer-ai.config.json"
      );
      const content = await vscode.workspace.fs.readFile(configUri);
      return JSON.parse(content.toString());
    } catch {
      return null;
    }
  }

  /**
   * Write workspace configuration
   */
  async writeWorkspaceConfig(config: TranslationConfig): Promise<void> {
    const workspaceFolder = vscode.workspace.workspaceFolders?.[0];
    if (!workspaceFolder) {
      throw new Error("No workspace folder is open");
    }

    const configUri = vscode.Uri.joinPath(
      workspaceFolder.uri,
      "localizer-ai.config.json"
    );
    const content = JSON.stringify(config, null, 2);
    await vscode.workspace.fs.writeFile(
      configUri,
      Buffer.from(content, "utf8")
    );
  }

  /**
   * Validate configuration
   */
  validateConfig(config: Partial<TranslationConfig>): string[] {
    const errors: string[] = [];

    if (!config.sourceLanguage) {
      errors.push("Source language is required");
    }

    if (!config.targetLanguages || config.targetLanguages.length === 0) {
      errors.push("At least one target language is required");
    }

    if (!config.fileTypes || config.fileTypes.length === 0) {
      errors.push("At least one file type is required");
    }

    if (!config.aiProvider) {
      errors.push("AI provider is required");
    }

    return errors;
  }
}
