const { GoogleGenerativeAI } = require("@google/generative-ai");
const { getApiKey } = require("../config/common");
const { getValueFromConfig } = require("../utils/common");

// Retrieve Gemini API key (set via `npm config set -g gemini-key YOUR_KEY`)
const apiKey = getApiKey("gemini-key");

// Validate API key exists
if (!apiKey) {
  throw new Error(
    "Gemini API key not found. Please set it via: npm config set -g gemini-key YOUR_KEY",
  );
}

// Initialize Gemini client
const genAI = new GoogleGenerativeAI(apiKey);
let llmConfig;

/**
 * Gets available models from Google Gemini API
 * @returns {Promise<string[]>} Array of available model names
 */
const getAvailableModels = async () => {
  try {
    const models = await genAI.listModels();
    return models.map((model) => model.name);
  } catch (error) {
    console.warn("Could not fetch available models:", error.message);
    return [];
  }
};

/**
 * Sends a question to Google Gemini and returns its response.
 * @param {Object} params
 * @param {string} params.question - The user question/content to send.
 * @param {string} params.systemPrompt - System instructions to guide the model.
 * @returns {Promise<string>} AI generated text.
 */
const askGeminiAI = async ({ question, systemPrompt }) => {
  if (!question) {
    throw new Error("Question is required");
  }

  if (!systemPrompt) {
    console.warn("System prompt is empty - this may affect response quality");
  }

  if (!llmConfig) {
    llmConfig = getValueFromConfig("llmConfig");
  }

  const preferredModel = (llmConfig && llmConfig.model) || "gemini-1.5-flash";

  // Updated model names without -latest suffix
  const fallbacks = [
    preferredModel,
    "gemini-1.5-pro",
    "gemini-1.5-flash",
    "gemini-pro",
  ];

  const tryModel = async (modelName) => {
    try {
      const model = genAI.getGenerativeModel({ model: modelName });
      const prompt = `${systemPrompt}\n\n${question}`;
      const result = await model.generateContent(prompt, {
        ...llmConfig,
      });

      console.log(`Successfully used model: ${modelName}`);
      return result.response.text();
    } catch (err) {
      console.warn(`Model ${modelName} failed:`, err.message);
      throw err;
    }
  };

  let lastError;
  for (const modelName of fallbacks) {
    try {
      return await tryModel(modelName);
    } catch (err) {
      lastError = err;

      // Check if it's a model not found error
      if (
        err.message?.includes("404") ||
        err.message?.includes("not found") ||
        err.message?.includes("not supported")
      ) {
        console.log(
          `Model ${modelName} not available, trying next fallback...`,
        );
        continue; // Try next model
      }

      // For other errors (auth, rate limit, etc.), don't continue
      console.error(
        `Non-recoverable error with model ${modelName}:`,
        err.message,
      );
      break;
    }
  }

  // If all attempts fail, throw a detailed error
  throw new Error(
    `All models failed. Tried models: ${fallbacks.join(", ")}. Last error: ${
      lastError.message
    }`,
  );
};

module.exports = { askGeminiAI, getAvailableModels };
